def parse_record(text, delimiter=","):
    """Split one delimited record into its fields. See TASK.md."""
    _validate_delimiter(delimiter)

    fields = []
    length = len(text)
    position = 0
    while True:
        if position < length and text[position] == '"':
            position += 1
            value = []
            while True:
                if position >= length:
                    raise ValueError("unterminated quoted field")
                character = text[position]
                if character != '"':
                    value.append(character)
                    position += 1
                elif position + 1 < length and text[position + 1] == '"':
                    value.append('"')
                    position += 2
                else:
                    position += 1
                    if position < length and text[position] != delimiter:
                        raise ValueError("characters after closing quote")
                    break
            fields.append("".join(value))
        else:
            start = position
            while position < length and text[position] != delimiter:
                if text[position] in "\n\r\"":
                    raise ValueError("invalid character in unquoted field")
                position += 1
            fields.append(text[start:position])

        if position == length:
            return fields
        position += 1
        if position == length:
            fields.append("")
            return fields


def format_record(fields, delimiter=","):
    """Write fields as one delimited record. See TASK.md."""
    _validate_delimiter(delimiter)
    try:
        fields = list(fields)
    except (TypeError, ValueError):
        raise ValueError("fields must be a non-empty iterable of strings")
    if not fields or any(not isinstance(field, str) for field in fields):
        raise ValueError("fields must be a non-empty iterable of strings")

    formatted = []
    for field in fields:
        needs_quotes = (
            delimiter in field
            or '"' in field
            or "\n" in field
            or "\r" in field
            or field.startswith(" ")
            or field.endswith(" ")
        )
        if needs_quotes:
            formatted.append('"' + field.replace('"', '""') + '"')
        else:
            formatted.append(field)
    return delimiter.join(formatted)


def _validate_delimiter(delimiter):
    if not isinstance(delimiter, str) or len(delimiter) != 1 or delimiter in '"\n\r':
        raise ValueError("delimiter must be one allowed character")
